def dehydrate_timedelta(value):
    """
    Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    if value is None:
        return None
    seconds = int(value.total_seconds())
    hours, remainder = divmod(seconds, 3600)
    minutes, seconds = divmod(remainder, 60)
    if hours > 0:
        return {
            'hours': hours,
            'minutes': minutes,
            'seconds': seconds
        }
    elif minutes > 0:
        return {
            'minutes': minutes,
            'seconds': seconds
        }
    else:
        return {
            'seconds': seconds
        }

