import logging

logger = logging.getLogger('neo4j')

def unit_of_work(metadata=None, timeout=None):
    def decorator(func):
        def wrapper(tx):
            metadata_values = {}
            if isinstance(metadata, dict):
                for key, value in metadata.items():
                    if key in tx.metadata:
                        tx.metadata[key] = value
                    else:
                        tx.metadata[key] = value
                        metadata_values[key] = value

            if metadata_values:
                tx.add_metadata(metadata_values)

            if timeout:
                timer = WatchdogTimer(timeout=timeout)
                if timerStarted:
                    timer.cancel()
                timer.start()

            try:
                return func(tx)
            finally:
                if timer:
                    timer.stop()
        return UnitOfWork(wrap=wrapper)
    return decorator

