    result = {field: None for field in self._fields}

    for i, key in enumerate(keys):
        if isinstance(key, int) and i < len(self._fields):
            result[self._fields[i]] = self._values[i]
        elif isinstance(key, str) and key in self._fields:
            result[key] = self._values[self._fields.index(key)]
