def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.

    Args:
        maxsize: The number of results to cache, defaults to 128.
        ttl: The time-to-live (TTL) in seconds for each result, defaults to 600 seconds.
        timer: A timer function to use, defaults to `time.monotonic`.
        typed: A boolean indicating whether to cache arguments of various types as different keys, defaults to False.

    Returns:
        A wrapper function that memoizes its results or else a function wrapper that does this.
    """

    def memoize(func):
        cache = {}
        ttl_cache = {}

        def _update_wrapper(wrapper, func):
            wrapper.__doc__ = func.__doc__
            wrapper.__name__ = func.__name__
            wrapper.__module__ = func.__module__
            wrapper.__class__ = func.__class__
            return wrapper

        def _ttl_set_timeout(key, expiration):
            ttl_cache[key] = expiration

        def _ttl_check_timeout(item):
            expiration = ttl_cache.get(item)
            if expiration is not None and expiration <= timer():
                return True
            return False

        def wrapper(*args, **kwargs):
            key = _create_key(args, kwargs, typed)

            if key in cache:
                result = cache[key]
                if not _ttl_check_timeout(result):
                    return result
                # Remove expired item from cache to free up space
                if _ttl_check_timeout(item):
                    del cache[item]

            result = func(*args, **kwargs)
            cache[key] = result

            ttl_cache[key] = timer() + ttl

            return result

