def extostr(cls, e, max_level=30, max_path_level=5):
    '''''
    Format an exception.
    :param e: Any exception instance.
    :type e: Exception
    :param max_level: Maximum call stack level (default 30)
    :type max_level: int
    :param max_path_level: Maximum path level (default 5)
    :type max_path_level: int
    :return The exception readable string
    :rtype str
    '''
    if max_level < 0:
        max_level = 0

    stack = traceback.extract_stack()
    stack = stack[:max_level]

    err_path = []
    for i, frame in enumerate(stack):
        if frame[2] != '<module>':
            err_path.append((frame[0], frame[1], frame[2], frame[3]))

    if len(err_path) > max_path_level:
        err_path = err_path[-max_path_level:]

    levels = []
    for i, (path, line, func, _src) in enumerate(err_path):
        if len(levels) > 0 and i == len(err_path) - 1:
            break
        levels.append('  ' * i + f'{path}:{line} -> {func}')

    info = {}
    if hasattr(e, '__traceback__'):
        info['traceback'] = ''.join(traceback.format_tb(e.__traceback__))
    if hasattr(e, 'message'):
        info['message'] = e.message
    elif hasattr(e, 'args'):
        info['message'] = str(e.args)

    return f'[{info.get("traceback", "")}].exc: {info.get("message", "")}'

