        ret['err:key'] = str(e)

    if isinstance(e, value types error):
        ret['err:value'] = str(e)

    if isinstance(e, AttributeError):
        ret['err:attr'] = str(e)

    if isinstance(e, TypeError):
        ret['err:typ'] = str(e)

