import collections

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    bases = collections.deque(set(classes))
    while bases:
        base = bases.popleft()
        extra = True
        for i in range(1, len(bases) + 1):
            if base in bases[-i]:
                extra = False
                break
        if extra:
            bases.appendleft(base)
    return list(bases)

