def minimalBases(classes: List["Constant"]) -> List["Constant"]:
    def sort_by(_cls):
        if hasattr(_cls, "name"):
            return _cls.name
        else:
            return str(id(_cls))

    queue = set(classes)
    remaining = set(classes)
    while remaining:
        next_queue = set()
        for _cls in remaining:
            for base in _cls.bases:
                if base not in queue:
                    next_queue.add(base)
                    queue.add(base)
        remaining = next_queue
    return sorted(classes, key=sort_by)

