def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not (-1 <= coord[0] <= self._xlen):
        raise ValueError("X coordinate is out of bounds: {}".format(coord[0]))
    if not (-1 <= coord[1] <= self._ylen):
        raise ValueError("Y coordinate is out of bounds: {}".format(coord[1]))

    self._data[int(self._xlen * (coord[0] + 1))][int(self._ylen * (coord[1] + 1))] += weight

def fill(self, coord, weight=1):
    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if coord < self.min_coord or coord > self.max_coord:
        return

    index = self.bin_index(coord)
    if index != self.size:
        self.data[index] += weight

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if type(coord) not in (list, tuple), len(coord) != 2:
        raise ValueError("coord must be a two-element list or tuple")
    x, y = coord
    if not self.is_in_edge(x, y):
        return
    self._data[x][y] += weight

