import re

def validate_value(value):
    """
    Validate the given value against the corresponding regular expression.

    Args:
        value: the string to validate

    Raises:
        ValidationError: if the given value is not conform to the regular expression.
    """
    if not isinstance(value, str):
        raise ValidationError('"{}" must be a string.'.format(value))

    regular_expression = getattr(self, 'RE', None)
    if not regular_expression:
        raise ValidationError('"RE" attribute not set for this validator.')

    try:
        pattern = re.compile(regular_expression)
        if not pattern.match(value):
            raise ValidationError('Value "{}" does not match the pattern {}'.format(value, regular_expression))
    except re.error as e:
        raise ValidationError('Error parsing regular expression: {}'.format(e))

