def formatmany(self, sql: AnyStr, many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]]):
    markers = {param: '?' for param in self.parameter_mock.values()}
    formatter = self.parameter_formatter.gsub(markers)

    formatted_sql, final_params = [], []
    for params in many_params:
        final_params.append([])
        for key, val in params.items():
            final_params[-1].append(formatter(key, val))

    final_params = [tuple(final) for final in final_params]

    return formatted_sql, final_params

def formatmany(self, sql: AnyStr, many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]]) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    param_placeholders = []
    params = []

    for params_chunk in many_params:
        if isinstance(params_chunk, dict):
            params_chunk_keys = list(params_chunk.keys())
            params_chunk_values = list(params_chunk.values())
            param_placeholders.append('({})'.format(','.join('%s' for _ in params_chunk_keys)))
            params.append([params_chunk_values[i] for i in range(len(params_chunk_keys))])
        elif isinstance(params_chunk, list):
            param_placeholders.append('({})'.format(','.join('%s' for _ in params_chunk)))
            params.append([params_chunk[i] for i in range(len(params_chunk))])
        else:
            raise ValueError("Unsupported params type; expected dict or list.")

    formatted_sql = sql.replace(':%s', param_placeholders[0]).replace('%(sql_param)s', param_placeholders[0])
    return formatted_sql, params

def formatmany(self, sql, many_params):
    # Check if SQLParams.in_style is named or ordinal
    in_style = self.SQLParams.in_style
    params_type = {}

    # Convert all parameters to the required type (Ensure they match with db metadata)
    for params in many_params:
        if isinstance(params, dict):
            params_type = params
        else:
            params_type =zip(params, range(len(params)))

    # Replace parameter markers in query with actual values
    formatted_sql = sql
    for param, value in params_type.items():
        if in_style == "named":
            formatted_sql = formatted_sql.replace(f":{param}", f"_{param}")
        elif in_style == "ordinal":
            formatted_sql = formatted_sql.replace("%s", str(value))

    formatted_params = []
    for params in many_params:
        if isinstance(params, dict):
            params = params.values()
        formatted_params.append(params)

    return formatted_sql, formatted_params

