def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """

    if inventory is None:
        raise ValueError("Inventory cannot be None.")

    if not isinstance(inventory, dict):
        raise TypeError("Inventory must be a dictionary.")

    spec_version = extract_spec_version if extract_spec_version else self.spec_version

    specification = self.inventory_specs.get(spec_version, None)

    if specification is None:
        raise ValueError("Invalid specification version.")

    errors = []

    for item_name, item_data in inventory.items():
        type_value = item_data.get('type', None)

        if type_value is None:
            errors.append(f"Item '{item_name}' does not have a 'type' value.")
        else:
            if isinstance(type_value, str):
                try:
                    schema = self.type_registry[type_value]
                except KeyError:
                    errors.append(f"Unknown type value '{type_value}' for item '{item_name}'.")
            else:
                try:
                    schema = self.type_registry[str(type_value)]
                except KeyError:
                    errors.append(f"Unknown type value '{type_value}' for item '{item_name}'.")

            if schema is None:
                errors.append(f"Unknown schema '{type_value}' for item '{item_name}'.")
            elif not schema.validate(item_data, item_name):
                errors.append(f"Item '{item_name}' does not conform to the 'type' schema.")

    if errors:
        raise ValueError("Validation errors encountered:", errors)

