def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}

    # Ensure the version is accessible from the inventory
    if version in inventory:
        inventory_version = inventory[version]

        # Iterate over logical paths and versions
        for logical_path, version_info in inventory_version.items():
            content_files = set()

            # Add current version content files if available
            if 'files' in version_info and logical_path in version_info['files']:
                content_files.update(version_info['files'][logical_path])

            # Add dependency version content files if available
            if 'dependencies' in version_info:
                for dep_version in version_info['dependencies']:
                    if dep_version in inventory and 'files' in inventory[dep_version]:
                        content_files.update(inventory[dep_version]['files'])

            logical_path_map[logical_path] = content_files

    else:
        raise ValueError(f"Version {version} not found in inventory.")

    return logical_path_map

