def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def process_expression(expr):
        if '|' in expr:
            return expr.replace(' | ', ') & (', ')))
        elif '&' in expr:
            return expr.replace(' & ', '(' & (', ')))
        else:
            return expr

    processed_args = [process_expression(arg) for arg in args]
    negative_absorptions = [(processed_args[i], processed_args[i+1]) for i in range(0, len(processed_args), 2) if i+1 < len(processed_args)]
    absorbenced_args = [processed_args[i] if not (absorption_args := args[i:i+2]) else absorption_args for i in range(len(processed_args)) if not any(absorption_args)]
    return absorbenced_args

