import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    command = []
    for path in commands:
        command.extend(path.split())

    try:
        output = subprocess.run(
            command,
            args=args,
            cwd=cwd,
            shell=False,
            text=True,
            env=env,
            check=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL if hide_stderr else subprocess.PIPE,
        )
        return output.stdout.strip()
    except subprocess.CalledProcessError as e:
        if hide_stderr:
            return f"Command failed: {e.stdout.strip()}"
        raise e

import subprocess

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s).

    :param commands: The command(s) to run.
    :param args: Additional arguments to pass to the command.
    :param cwd: Current working directory where the command should be executed.
    :param verbose: Whether to display verbose output.
    :param hide_stderr: Whether to hide the standard error output.
    :param env: Environment variables to set during the command execution.
    """
    full_command = []
    full_command.extend(commands)
    for arg in args:
        full_command.append(arg)
    try:
        if cwd is not None:
            full_command.append(cwd)
        if hide_stderr:
            command = full_command + ['> /dev/null']
            output = subprocess.check_output(command, env=env, shell=False)
        else:
            output = subprocess.check_output(full_command, env=env, shell=False)
    except subprocess.CalledProcessError:
        msg = "couldn't run command\n{}".format(' '.join(full_command))
        raise ProgramError(msg)
    return output.strip()

