    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    for idx, (version_dir, version_file) in enumerate(version_dirs):
        if idx == 0:
            try:
                packaging.version.Version(version_file)
            except InvalidVersion as error:
                tmpl = (
                    "Inventory file {version_file!r} must have a version number;"
                    " {error}"
                )
                raise DistutilsSetupError(tmpl.format(version_file=version_file, error=error))

        with open(version_file, 'r') as h:
            inventory = h.read()
            if not inventory.startswith(version):
                tmpl = (
                    "Inventory file {version_file!r} must have the version {version!r} "
                    "at the beginning; instead found: {inventory!r}"
                )
                raise DistutilsSetupError(tmpl.format(
                    version_file=version_file, version=version,
                    inventory=inventory
                ))

