def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """

    try:
        with open(path, 'r') as fobj:
            first_line = fobj.readline().strip()

            if first_line.startswith('0=*='):
                return 'root'
            elif first_line.startswith('0=*=Object'):
                return 'object'
            elif first_line.startswith('0=*=File'):
                return 'file'
            else:
                return 'other'
    except Exception as e:
        if isinstance(e, FileNotFoundError):
            return 'file not found'
        elif isinstance(e, PermissionError):
            return 'permission denied'
        else:
            return f'error: {str(e)}'

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    if not path.startswith("0=*"):
        return "error: input path does not start with '0=*'"
    if not path.endswith("/"):
        path += "/"
    if not path.endswith("Namaste"):
        return "error: input path is not in '0=*>Namaste' format"
    if len(path) <= len("0=*>Namaste/"):
        return "error: input path is too short"
    if any(char not in path[i+1] for i, char in enumerate(path[6:])):
        return "error: input path is not valid"
    if any(char.isdigit() for char in path):
        return "error: input path contains numeric characters"

    return path.split("/")[-2]

