def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.

    Args:
        parser (argparse.ArgumentParser): The parser instance.
    """
    return ' '.join(f'-{k}'
                   for k, v in parser._option_string_actions.items()
                   if not v.hidden and v.default is None)

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    flags = []
    for action in parser._get_active_arguments():
        if not action.option_strings[0].startswith('--') or action.option_strings[0] == ('-' * (len(action.option_strings[0]) + 2)):
            continue
        flags.append(action.option_strings[0])
    return ' '.join(flags)

