    result, remaining_arguments = {}, []
    for subparser_name, parser in subparsers.items():
        try:
            subparser_result = parser.parse_args(unparsed_arguments)
            result[subparser_name] = subparser_result
        except SystemExit:
            remaining_arguments.extend(unparsed_arguments)
    return result, remaining_arguments

def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_namspaces = {}
    remaining_arguments = []

    for arg in unparsed_arguments:
        for name, parser in subparsers.items():
            if parser.is_parser_for arg:
                try:
                    namespace = parser.parse_known_args([arg])[0]
                    parsed_namspaces[name] = namespace
                    break
                except Exception as e:
                    if not isinstance(e, argparse.ArgumentTypeError) and not isinstance(e, AttributeError):
                        raise

        remaining_arguments.append(arg)

    return parsed_namspaces, remaining_arguments

