def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        sign = '-'
        number = -number
    else:
        sign = ''

    if padding is not None:
        number_str = format(number, f'>{padding}d')
    else:
        number_str = str(number)

    reversed_str = number_str[::-1]

    res = ''
    for digit in reversed_str:
        res += alphabet[int(digit)]

    return sign + res

from typing import List, Optional

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if number < 0:
        return '-' + int_to_string(-number, alphabet, padding)
    elif not alphabet:
        return str(number)

    result = ''
    while number > 0:
        result = alphabet[number % len(alphabet)] + result
        number //= len(alphabet)

    if padding is not None:
        result = ('{:' + str(padding) + '}').format(result)

    return result

