def prepare_repository_from_archive(archive_path: str, filename: Optional[str] = None, tmp_path: Union[PosixPath, str] = "/tmp"):
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    try:
        if not os.path.isfile(archive_path):
            raise FileNotFoundError(f"Archive {archive_path} not found")

        if not filename:
            filename = os.path.basename(archive_path)

        with subprocess.Popen(["tar", "-zxvf", archive_path, "--exclude=meta/*.txt"], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True) as process:
            output, error = process.communicate()

        if process.returncode != 0:
            raise subprocess.CalledProcessError(process.returncode, command=["tar", "-zxvf", archive_path, "--exclude=meta/*.txt"], output=output, error=error)

        repo_url = os.path.join(tmp_path,.filename)
        shutil.move(os.path.join(tmp_path, "meta"), repo_url)
        return repo_url
    except FileNotFoundError as e:
        raise e

