import subprocess

def addignored(ignored):
    def git(args, error_message, cwd=None, **error_kwargs):
        output, status = command_output("git {0}".format(args), cwd=cwd)
        if status != 0:
            error_kwargs['output'] = output
            error_kwargs['directory'] = cwd
            raise HarpoonError(error_message, **error_kwargs)
        return output

    ignored_files = git("ls-files --exclude-standard", "Failed to find ignored files")

    try:
        ignored_files = [fnmatch.filter(ignored_files, ignored_regex)[0] for ignored_regex in ignored if fnmatch.fnmatch(ignored_files, ignored_regex)]
    except IndexError:
        ignored_files = [fnmatch.fnmatch(ignored_files, ignored_regex)[0] for ignored_regex in ignored if fnmatch.fnmatch(ignored_files, ignored_regex)]

    ignored_files.sort()

    return ','.join(ignored_files)

