def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.

    :param config_filenames: Tuple of (string) configuration filenames
    :param overrides: (dict) to use as only configuration or to override existing ones
    :param resolve_env: (boolean) whether to resolve environment variables in the config files

    :return: A tuple of (dict, list) where:
        - dict: A dictionary mapping configuration filenames to their parsed configurations
        - list: A list of logging.LogRecord instances containing any parse errors
    """
    parsed_configurations = {}
    log_records = []

    try:
        for config_filename in config_filenames:
            add_config(parsed_configurations, config_filename, overrides, resolve_env)
    except Exception as e:
        log_records.append(logging.makeLogRecord({
            'name': 'load_configurations',
            'levelname': 'ERROR',
            'message': str(e)
        }))

    return parsed_configurations, log_records


