    '''Try to identify whether this is a Matrix request

    Args:
      request: RequestType

    Returns:
      bool
    '''
    if 'MATRIX_HOME_SERVER_URL' in request.headers.get('X-FORWARDED-FOR', '').split(','):
        return True
    elif 'CALL-DAY-DST' in request.headers.get('X-FORWARDED-FOR', '').split(','):
        return True
    else:
        return False

