def verify_relayable_signature(public_key, doc, signature):
    # Parse the XML document
    root = ET.fromstring(doc)

    # Verify the signature of the document
    if root.find('Signature') is not None:
        try:
            # Validate the signature using the public key
            if root.find('Signature').find('SignatureValue').text == public_key:
                return True
            else:
                return False
        except Exception as e:
            return False
    else:
        return False

