    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def _monkeypatch(json.load):
        def inner(file):
            if file.name.endswith('.json'):
                data = json.load(file)
                # Add property 'plugin dir' to each plugin in data
                for plugin in data.get('plugins', []):
                    plugin['plugin_dir'] = plugin_dir
            return data
        json.load = inner

