    import os
    import json

    def _monkeypatch(json.load):
        def inner(file):
            if file.name.endswith('.json'):
                data = json.load(file)
                # Add property 'plugin dir' to each plugin in data
                for plugin in data.get('plugins', []):
                    plugin['plugin_dir'] = plugin_dir
            return data
        json.load = inner

    imported_plugins = []

    def _import_plugin(plugin_name, plugin_dir):
        # Register imported plugins
        imported_plugins.append(plugin_name)

        # Dynamically import the plugin file
        __import__(plugin_name, fromlist=[''])

    pysdkfiles = os.listdir(plugin_dir)
    for pyfile in pysdkfiles:
        if pyfile.startswith("__") or pyfile.endswith("_test.py"): continue
        if pyfile.endswith(".py"):
            if pyfile == "__init__.py": continue
            plugin_name = pyfile.split(".")[0]
            _import_plugin(plugin_name, plugin_dir)

    res = {}
    for imported_plugin in imported_plugins:
        plugin_module = __import__(imported_plugin, fromlist=[''])
        try:
            plugin_spec = getattr(plugin_module, 'Spec')
            plugins = getattr(plugin_spec, 'plugins')
            for plugin in plugins:
                plugin_name = plugin['name']
                res[plugin_name] = plugin['properties']
        except Exception as e:
            print(f"Error loading {imported_plugin}: {e}")

    del json.load

    return res

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    plugin_spec = {}
    for root, dirs, files in os.walk(plugin_dir):
        for file in files:
            if file.endswith('.json'):
                file_path = os.path.join(root, file)
                with open(file_path, 'r', encoding='utf-8') as f:
                    plugin_data = json.load(f)
                    plugin_spec.update(plugin_data)
    return plugin_spec

